ext('c12_eco_ch2',[
C("🍬","एक उदाहरण: समोसे की उपयोगिता",["पहला समोसा: बहुत संतुष्टि","दूसरा समोसा: कुछ कम","तीसरे में और कम","चौथे पर संतुष्टि लगभग शून्य"],"मान लीजिए आप भूखे हैं और समोसा खाते हैं। पहले समोसे से आपको बहुत संतुष्टि मिलती है। दूसरे से थोड़ी कम, और तीसरे से उससे भी कम। चौथे तक पहुँचते-पहुँचते आपको लगभग कुछ नहीं मिलता। इसी को ह्रासमान सीमांत उपयोगिता का नियम कहते हैं। इससे ही समझ आता है कि लोग हर चीज़ की सीमित मात्रा ही क्यों खरीदते हैं।"),
C("💰","माँग की तालिका और वक्र",["कीमत घटे तो माँग बढ़े","तालिका में कीमत और मात्रा","वक्र बाएँ से दाएँ नीचे की ओर","विपरीत संबंध का चित्र"],"माँग की तालिका में अलग-अलग कीमतों पर उपभोक्ता की माँगी गई मात्रा लिखी जाती है। जैसे कीमत दस रुपये हो तो माँग सौ इकाई, और पाँच रुपये हो तो माँग दो सौ इकाई। इन्हें ग्राफ़ पर दिखाएँ तो वक्र बाएँ से दाएँ नीचे की ओर जाता है। यह कीमत और माँग के विपरीत संबंध को दिखाता है।"),
C("↔️","माँग वक्र पर गति और खिसकाव",["कीमत बदली: वक्र पर गति","दूसरे कारण बदले: वक्र खिसकता","आय बढ़ना: दाएँ खिसकाव","पसंद घटना: बाएँ खिसकाव"],"जब केवल उस वस्तु की कीमत बदलती है, तो हम उसी वक्र पर ऊपर या नीचे चलते हैं। इसे माँग में गति कहते हैं। जब आय, रुचि या संबंधित वस्तुओं की कीमत जैसे दूसरे कारण बदलते हैं, तो पूरा वक्र खिसकता है। आय बढ़े तो वक्र दाएँ खिसकता है, और पसंद घटे तो बाएँ।"),
C("🔀","स्थानापन्न और पूरक वस्तुएँ",["चाय और कॉफ़ी: स्थानापन्न","चाय और चीनी: पूरक","स्थानापन्न महँगा तो माँग बढ़ती","पूरक महँगा तो माँग घटती"],"स्थानापन्न वस्तुएँ एक-दूसरे के बदले इस्तेमाल हो सकती हैं, जैसे चाय और कॉफ़ी। अगर कॉफ़ी महँगी हो जाए तो लोग चाय ज़्यादा खरीदते हैं। पूरक वस्तुएँ साथ-साथ इस्तेमाल होती हैं, जैसे चाय और चीनी। अगर चीनी महँगी हो जाए तो चाय की माँग भी थोड़ी घट सकती है।"),
C("📉","माँग की कीमत लोच की माप",["प्रतिशत परिवर्तन की तुलना","लोच एक से ज़्यादा: लोचदार","लोच एक से कम: बेलोचदार","आवश्यक वस्तुओं की लोच कम"],"माँग की कीमत लोच बताती है कि कीमत बदलने पर माँग कितनी बदलती है। इसे माँग में प्रतिशत परिवर्तन को कीमत में प्रतिशत परिवर्तन से भाग देकर निकालते हैं। मान एक से ज़्यादा हो तो माँग लोचदार है, और कम हो तो बेलोचदार। नमक और दवा जैसी आवश्यक वस्तुओं की माँग प्रायः बेलोचदार होती है।"),
C("🧮","बजट रेखा का अर्थ",["आय सीमित होती है","दो वस्तुओं के संयोजन","खरीदी जा सकने वाली सीमा","आय बढ़ने पर रेखा बाहर खिसके"],"उपभोक्ता की आय सीमित होती है, इसलिए वह सब कुछ नहीं खरीद सकता। बजट रेखा उन सभी संयोजनों को दिखाती है जो आय के भीतर खरीदे जा सकते हैं। रेखा के भीतर की सभी जगहें खरीदी जा सकती हैं। आय बढ़ने पर बजट रेखा बाहर की ओर खिसकती है, और कीमत बढ़ने पर भीतर की ओर।"),
],5)
ext('c12_eco_ch3',[
C("🏭","अल्पकाल और दीर्घकाल",["अल्पकाल: कुछ कारक स्थिर","दीर्घकाल: सब कारक परिवर्तनशील","फ़ैक्टरी का आकार बदलना","फ़र्म का निर्णय अलग-अलग"],"उत्पादन में अल्पकाल वह अवधि है जिसमें कम से कम एक कारक, जैसे मशीन या इमारत, नहीं बदली जा सकती। दीर्घकाल में सभी कारक बदले जा सकते हैं, यहाँ तक कि नई फ़ैक्टरी भी लगाई जा सकती है। इसलिए फ़र्म के निर्णय दोनों अवधियों में अलग-अलग होते हैं, और लागत के नियम भी बदल जाते हैं।"),
C("📊","कुल और सीमांत उत्पाद का संबंध",["सीमांत उत्पाद: एक अतिरिक्त इकाई से बढ़ोतरी","पहले बढ़ता, फिर घटता","जब शून्य हो तो कुल उत्पाद अधिकतम","ऋणात्मक हो तो कुल उत्पाद घटता"],"सीमांत उत्पाद वह अतिरिक्त उत्पादन है जो एक अतिरिक्त श्रमिक लगाने से मिलता है। शुरू में यह बढ़ता है और बाद में घटने लगता है। जब सीमांत उत्पाद शून्य हो जाता है, तो कुल उत्पाद सबसे ज़्यादा होता है। अगर सीमांत उत्पाद ऋणात्मक हो जाए, तो कुल उत्पाद भी घटने लगता है।"),
C("🧱","खेत में परिवर्ती अनुपात का उदाहरण",["एक खेत, कई मज़दूर","पहले मज़दूर से बड़ा लाभ","बहुत भीड़ से घटता उत्पादन","ह्रासमान प्रतिफल"],"मान लीजिए एक खेत में केवल एक मज़दूर है, तो वह हर काम अकेला करेगा और खेत अधूरा रहेगा। दूसरा और तीसरा मज़दूर लगाने से उत्पादन तेज़ी से बढ़ेगा। लेकिन उसी खेत में बहुत ज़्यादा मज़दूर हो जाएँ तो वे एक-दूसरे के काम में बाधा बनेंगे। तब हर नए मज़दूर से उत्पादन में वृद्धि घटने लगती है।"),
C("💸","लागत के बीच संबंध",["कुल लागत: स्थिर और परिवर्ती का जोड़","औसत लागत: प्रति इकाई लागत","सीमांत लागत: अतिरिक्त इकाई की लागत","सीमांत लागत नीचे हो तो औसत घटती"],"कुल लागत में स्थिर और परिवर्ती लागत दोनों होती हैं। औसत लागत प्रति इकाई लागत है, और सीमांत लागत एक अतिरिक्त इकाई बनाने की नई लागत। जब सीमांत लागत औसत लागत से कम होती है, तो औसत लागत घटती है। जब सीमांत लागत औसत से ज़्यादा हो जाती है, तब औसत लागत बढ़ने लगती है।"),
C("📈","आगम की धारणाएँ",["कुल आगम: बिक्री से कुल आय","औसत आगम: प्रति इकाई आय","सीमांत आगम: अतिरिक्त इकाई से आय","लाभ: आगम और लागत का अंतर"],"कुल आगम वह कुल धन है जो फ़र्म को बिक्री से मिलता है। औसत आगम प्रति इकाई मिलने वाली आय है, जो कीमत के बराबर होती है। सीमांत आगम वह अतिरिक्त आय है जो एक और इकाई बेचने से मिलती है। लाभ कुल आगम और कुल लागत का अंतर होता है।"),
C("🏗️","पैमाने के प्रतिफल",["सब कारक बढ़ाने पर उत्पादन","वर्धमान प्रतिफल","स्थिर प्रतिफल","ह्रासमान प्रतिफल"],"जब दीर्घकाल में सभी कारकों को एक ही अनुपात में बढ़ाया जाता है, तो उत्पादन कई तरह से बदल सकता है। अगर उत्पादन कारकों से ज़्यादा अनुपात में बढ़े तो वर्धमान प्रतिफल कहते हैं। बराबर अनुपात में बढ़े तो स्थिर प्रतिफल, और कम अनुपात में बढ़े तो ह्रासमान प्रतिफल।"),
],5)
ext('c12_eco_ch4',[
C("🌾","पूर्ण प्रतिस्पर्धा का उदाहरण",["गेहूँ की मंडी","बहुत से किसान और खरीदार","एक जैसी वस्तु","कोई अकेला कीमत तय नहीं करता"],"गेहूँ की मंडी को पूर्ण प्रतिस्पर्धा के पास का उदाहरण मान सकते हैं। यहाँ बहुत से किसान और बहुत से खरीदार हैं। गेहूँ लगभग एक जैसा होता है। कोई भी अकेला किसान कीमत को नहीं बदल सकता। हर किसान बाज़ार में तय हुई कीमत को ही मानकर चलता है, इसलिए उसे कीमत ग्रहण करने वाला कहते हैं।"),
C("📏","कीमत ग्रहणकर्ता फ़र्म का आगम",["कीमत स्थिर रहती है","औसत आगम बराबर कीमत","सीमांत आगम भी बराबर कीमत","माँग वक्र पड़ी रेखा"],"पूर्ण प्रतिस्पर्धा में फ़र्म को बाज़ार की कीमत स्वीकार करनी पड़ती है। इसलिए कितनी भी इकाइयाँ बेचे, कीमत वही रहती है। इसका मतलब यह है कि औसत आगम और सीमांत आगम दोनों कीमत के बराबर होते हैं। फ़र्म के लिए माँग वक्र एक पड़ी हुई सीधी रेखा होती है।"),
C("🎯","लाभ अधिकतम करने का बिंदु",["सीमांत आगम बराबर सीमांत लागत","सीमांत लागत बढ़ती हुई हो","उसी मात्रा पर उत्पादन करें","उससे आगे घाटा बढ़ने लगता"],"फ़र्म तब सबसे ज़्यादा लाभ कमाती है जब सीमांत आगम सीमांत लागत के बराबर हो जाता है। उस समय तक हर अतिरिक्त इकाई लाभ बढ़ाती है। इस बिंदु के बाद अगली इकाई की लागत उसके आगम से ज़्यादा हो जाती है, इसलिए उत्पादन बढ़ाने से लाभ घटने लगता है।"),
C("🛑","उत्पादन बंद करने का बिंदु",["कीमत औसत परिवर्ती लागत से कम","परिवर्ती लागत भी नहीं निकलती","अल्पकाल में उत्पादन बंद","स्थिर लागत फिर भी चुकानी"],"अल्पकाल में अगर कीमत औसत परिवर्ती लागत से भी कम हो जाए, तो फ़र्म को उत्पादन बंद कर देना चाहिए। क्योंकि उत्पादन जारी रखने से परिवर्ती लागत भी नहीं निकलती। उत्पादन बंद करने पर केवल स्थिर लागत का नुकसान होता है, जो वैसे भी चुकानी ही पड़ती है।"),
C("📦","पूर्ति की लोच",["कीमत बदलने पर पूर्ति में बदलाव","लोचदार पूर्ति","बेलोचदार पूर्ति","समय की अवधि का असर"],"पूर्ति की लोच बताती है कि कीमत बदलने पर पूर्ति कितनी बदलती है। जिन वस्तुओं का उत्पादन आसानी से बढ़ाया जा सके, उनकी पूर्ति लोचदार होती है। कृषि उत्पादों की पूर्ति प्रायः कम लोचदार होती है, क्योंकि फ़सल उगाने में समय लगता है। समय जितना ज़्यादा मिले, पूर्ति उतनी ज़्यादा लोचदार होती जाती है।"),
C("🏁","दीर्घकाल में सामान्य लाभ",["अधिक लाभ देखकर नई फ़र्में आती","पूर्ति बढ़ने से कीमत घटती","असाधारण लाभ घटकर शून्य","सामान्य लाभ पर संतुलन"],"अगर दीर्घकाल में फ़र्में असाधारण लाभ कमाएँ, तो नई फ़र्में उद्योग में प्रवेश करने लगती हैं। इससे पूर्ति बढ़ती है और कीमत घट जाती है। यह तब तक चलता है जब तक असाधारण लाभ शून्य न हो जाए और केवल सामान्य लाभ बचे। इसी बिंदु पर उद्योग संतुलन में आ जाता है।"),
],5)
ext('c12_eco_ch5',[
C("🥭","आम के बाज़ार में संतुलन",["ऊँची कीमत: पूर्ति ज़्यादा, माँग कम","नीची कीमत: माँग ज़्यादा, पूर्ति कम","बीच में एक कीमत जहाँ बराबरी","वही संतुलन कीमत"],"मान लीजिए आम की कीमत बहुत ऊँची है। तब किसान ज़्यादा बेचना चाहेंगे पर खरीदार कम होंगे, यानी अधिशेष होगा। कीमत बहुत नीची हो तो खरीदार ज़्यादा और बेचने वाले कम होंगे, यानी कमी होगी। इन दोनों के बीच एक कीमत ऐसी होती है जहाँ माँग और पूर्ति बराबर होती है। यही संतुलन कीमत है।"),
C("⚖️","संतुलन की ओर लौटने की प्रक्रिया",["अधिशेष पर कीमत घटती","कमी पर कीमत बढ़ती","बाज़ार खुद संतुलन खोजता","अदृश्य हाथ का विचार"],"जब बाज़ार में अधिशेष होता है, तो बेचने वाले कीमत घटाते हैं ताकि माल बिक सके। जब कमी होती है, तो खरीदार ज़्यादा कीमत देने को तैयार हो जाते हैं और कीमत बढ़ती है। इस तरह बिना किसी के आदेश के बाज़ार धीरे-धीरे संतुलन की ओर लौट आता है।"),
C("🔄","माँग और पूर्ति दोनों बदलने पर",["माँग और पूर्ति दोनों बढ़ें","मात्रा निश्चित रूप से बढ़ती","कीमत का असर अनिश्चित","बदलाव के सापेक्ष आकार पर निर्भर"],"कई बार माँग और पूर्ति एक साथ बदल जाती हैं। मान लीजिए दोनों बढ़ें। तब संतुलन मात्रा निश्चित रूप से बढ़ेगी। लेकिन कीमत बढ़ेगी, घटेगी या वही रहेगी, यह इस पर निर्भर करता है कि कौन-सा परिवर्तन ज़्यादा बड़ा है। इसलिए कीमत का असर पहले से कहा नहीं जा सकता।"),
C("🧾","सरकारी हस्तक्षेप: उदाहरण",["राशन में गेहूँ की उच्चतम कीमत","न्यूनतम समर्थन मूल्य","उच्चतम कीमत से कमी","न्यूनतम कीमत से अधिशेष"],"सरकार कभी-कभी बाज़ार में दखल देती है। गरीबों को सस्ता अनाज देने के लिए वह उच्चतम कीमत तय कर सकती है, पर इससे माँग बढ़कर कमी पैदा होती है। किसानों की सहायता के लिए वह न्यूनतम समर्थन मूल्य घोषित करती है, पर यह कीमत संतुलन से ऊपर हो तो अधिशेष पैदा होता है, जिसे सरकार को खरीदना पड़ता है।"),
C("📉","संतुलन में बदलाव का क्रम",["सबसे पहले कौन-सा वक्र खिसका","फिर नई संतुलन कीमत","नई संतुलन मात्रा","मूल से तुलना करना"],"संतुलन में बदलाव समझने के लिए एक आसान क्रम अपनाएँ। पहले पहचानिए कि माँग वक्र खिसका या पूर्ति वक्र। फिर देखिए कि वह दाएँ खिसका या बाएँ। उसके बाद नया कटाव बिंदु ढूँढ़िए। यही नई संतुलन कीमत और मात्रा होगी। इन्हें पुराने संतुलन से मिलाकर देखें।"),
],5)
ext('c12_eco_ch7',[
C("🧮","मौद्रिक प्रवाह: चक्रीय प्रवाह",["परिवार साधन बेचते हैं","फ़र्में उन्हें खरीदती हैं","फ़र्में वस्तुएँ बेचती हैं","परिवार वस्तुएँ खरीदते हैं"],"अर्थव्यवस्था में धन एक चक्र की तरह घूमता है। परिवार फ़र्मों को श्रम और पूँजी जैसे साधन देते हैं और बदले में आय पाते हैं। फ़र्में वस्तुएँ बनाकर परिवारों को बेचती हैं और उनसे धन वापस लेती हैं। इस तरह आय और व्यय का चक्र लगातार चलता रहता है। राष्ट्रीय आय इसी चक्र को मापती है।"),
C("🍞","अंतिम और मध्यवर्ती वस्तुएँ",["अंतिम वस्तु: उपभोग के लिए","मध्यवर्ती वस्तु: आगे उत्पादन में","आटा बेकरी के लिए मध्यवर्ती","ब्रेड घर के लिए अंतिम"],"जो वस्तुएँ सीधे उपभोग या निवेश के लिए तैयार हों, वे अंतिम वस्तुएँ हैं। जो वस्तुएँ आगे उत्पादन में काम आती हैं, वे मध्यवर्ती वस्तुएँ हैं। जैसे, बेकरी के लिए खरीदा गया आटा मध्यवर्ती है, और घर में खाई जाने वाली ब्रेड अंतिम वस्तु है। जीडीपी में केवल अंतिम वस्तुएँ गिनी जाती हैं, ताकि दोहरी गणना न हो।"),
C("📏","मूल्यवर्धन विधि का उदाहरण",["किसान गेहूँ बेचता: सौ रुपये","चक्की आटा बेचती: एक सौ बीस","बेकरी ब्रेड बेचती: एक सौ अस्सी","कुल मूल्यवर्धन एक सौ अस्सी"],"मान लीजिए किसान गेहूँ सौ रुपये का बेचता है। चक्की उसे आटा बनाकर एक सौ बीस रुपये का बेचती है, यानी बीस रुपये मूल्यवर्धन। बेकरी ब्रेड बनाकर एक सौ अस्सी रुपये की बेचती है, यानी साठ रुपये और जुड़े। कुल मूल्यवर्धन सौ, बीस और साठ मिलाकर एक सौ अस्सी रुपये होता है, जो ब्रेड की अंतिम कीमत के बराबर है।"),
C("🏦","घरेलू और राष्ट्रीय का फ़र्क",["घरेलू: देश की सीमा के भीतर","राष्ट्रीय: देश के सामान्य निवासियों द्वारा","विदेश से शुद्ध साधन आय जोड़ें","दोनों में यही अंतर"],"घरेलू उत्पाद देश की भौगोलिक सीमा के भीतर हुए उत्पादन को मापता है, चाहे उत्पादन करने वाला कोई भी हो। राष्ट्रीय उत्पाद देश के सामान्य निवासियों द्वारा किए गए उत्पादन को मापता है, चाहे वे देश के भीतर हों या बाहर। दोनों में अंतर विदेश से प्राप्त शुद्ध साधन आय का होता है।"),
C("🌍","जीडीपी की सीमाएँ",["गृहकार्य नहीं गिना जाता","असमानता नहीं दिखती","पर्यावरण का नुकसान नहीं","जीवन की गुणवत्ता का पूरा माप नहीं"],"जीडीपी देश की आर्थिक गतिविधि का एक उपयोगी माप है, लेकिन इसकी कुछ सीमाएँ हैं। घर में किए गए काम का मूल्य इसमें नहीं गिना जाता। यह नहीं बताता कि आय किसके पास कितनी है। पर्यावरण को हुआ नुकसान भी इसमें घटता नहीं। इसलिए जीडीपी से जीवन की गुणवत्ता का पूरा पता नहीं चलता।"),
C("💴","नाममात्र और वास्तविक जीडीपी का उदाहरण",["कीमतें दोगुनी, उत्पादन वही","नाममात्र जीडीपी दोगुनी","वास्तविक जीडीपी वही","वास्तविक से विकास की सही जानकारी"],"मान लीजिए किसी साल कीमतें दोगुनी हो जाएँ पर वस्तुओं की मात्रा वही रहे। तब नाममात्र जीडीपी दोगुनी दिखेगी, पर देश में असल में कोई बढ़ोतरी नहीं हुई। वास्तविक जीडीपी आधार वर्ष की कीमतों पर निकाली जाती है, इसलिए वह बदली हुई मात्रा ही दिखाती है। विकास की सही तस्वीर वास्तविक जीडीपी से मिलती है।"),
],5)
ext('c12_eco_ch11',[
C("🌏","विदेशी व्यापार के लाभ",["जो सस्ता बनाएँ वही निर्यात","जो महँगा पड़े उसका आयात","उपभोक्ताओं को अधिक विकल्प","तकनीक और पूँजी का आदान-प्रदान"],"खुली अर्थव्यवस्था में देश दूसरे देशों से व्यापार कर सकते हैं। हर देश उन वस्तुओं का निर्यात करता है जिन्हें वह सस्ता बना सकता है और बाकी वस्तुओं का आयात करता है। इससे उपभोक्ताओं को ज़्यादा विकल्प मिलते हैं और कीमतें कम रहती हैं। साथ ही तकनीक और पूँजी का भी आदान-प्रदान होता है।"),
C("💱","विनिमय दर का उदाहरण",["एक डॉलर के बराबर कितने रुपये","रुपया कमज़ोर: डॉलर महँगा","आयात महँगा, निर्यात सस्ता","रुपया मज़बूत: उलटा असर"],"विनिमय दर वह कीमत है जिस पर एक देश की मुद्रा दूसरे देश की मुद्रा में बदली जाती है। मान लीजिए एक डॉलर पहले अस्सी रुपये का था और अब नब्बे का हो गया। तब रुपया कमज़ोर हुआ। इससे विदेशी सामान महँगा हो जाता है, पर विदेश में हमारे सामान सस्ते लगने लगते हैं, जिससे निर्यात बढ़ने की संभावना रहती है।"),
C("📊","चालू खाता और पूँजी खाता",["चालू खाता: वस्तुएँ, सेवाएँ, हस्तांतरण","पूँजी खाता: निवेश और ऋण","चालू खाता घाटे में हो सकता","पूँजी खाते से उसकी भरपाई"],"भुगतान संतुलन के दो मुख्य खाते होते हैं। चालू खाता वस्तुओं, सेवाओं और हस्तांतरणों के लेन-देन को दिखाता है। पूँजी खाता विदेशी निवेश और ऋण जैसे वित्तीय लेन-देन को दर्ज करता है। अगर चालू खाते में घाटा हो, तो उसकी भरपाई प्रायः विदेशी पूँजी के आगमन से की जाती है।"),
C("🏛️","निर्धारित और लचीली विनिमय दर",["निर्धारित: सरकार तय करती है","लचीली: बाज़ार की माँग-पूर्ति से","प्रबंधित तैरती दर","भारत में प्रबंधित प्रणाली"],"कुछ देशों में सरकार विनिमय दर पहले से निर्धारित कर देती है, इसे निर्धारित दर कहते हैं। लचीली दर में विदेशी मुद्रा की माँग और पूर्ति से दर तय होती है। कई देश बीच का रास्ता अपनाते हैं, जिसमें दर बाज़ार से तय होती है पर ज़रूरत पड़ने पर केंद्रीय बैंक दखल देता है। भारत में यही प्रबंधित तैरती दर की प्रणाली है।"),
C("💼","भुगतान संतुलन में असंतुलन",["आयात ज़्यादा, निर्यात कम","विदेशी मुद्रा भंडार घटना","कर्ज़ बढ़ने का खतरा","निर्यात बढ़ाने की नीतियाँ"],"जब किसी देश का आयात निर्यात से बहुत ज़्यादा हो जाता है, तो भुगतान संतुलन में घाटा होता है। इस घाटे की भरपाई के लिए या तो विदेशी मुद्रा भंडार खर्च होता है या कर्ज़ लेना पड़ता है। लंबे समय तक यह चलता रहे तो देश की अर्थव्यवस्था पर जोखिम बढ़ जाता है, इसलिए निर्यात बढ़ाने की नीतियाँ अपनाई जाती हैं।"),
],5)
